import{_ as o,c as t,o as i,ag as n}from"./chunks/framework.Bzez9NG9.js";const h=JSON.parse('{"title":"Google BigQuery","description":"Configure Google BigQuery connections in SPACE using Google OAuth or service-account authentication.","frontmatter":{"title":"Google BigQuery","description":"Configure Google BigQuery connections in SPACE using Google OAuth or service-account authentication.","keywords":["Google BigQuery","Google Cloud","connections","OAuth","SSO","service account","service account JSON","BigQuery Data Viewer","BigQuery Job User","job credentials"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/connections/bigquery.md","filePath":"doc/configuration/connections/bigquery.md"}'),r={name:"doc/configuration/connections/bigquery.md"};function a(s,e,c,l,u,g){return i(),t("div",null,e[0]||(e[0]=[n('<h1 id="google-bigquery" tabindex="-1">Google BigQuery <a class="header-anchor" href="#google-bigquery" aria-label="Permalink to &quot;Google BigQuery&quot;">​</a></h1><p>Google BigQuery connections allow SPACE to query BigQuery data directly and use it as a connected data source, including alongside IBM Planning Analytics in SPACE AI.</p><p>A BigQuery connection represents one <strong>Google Cloud project and BigQuery dataset</strong>.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Identify the Google Cloud project and BigQuery dataset that SPACE should access.</p><p>For standard read-only use, the Google identity used by SPACE should have:</p><ul><li><strong>BigQuery Job User</strong> (<code>roles/bigquery.jobUser</code>) on the project where SPACE executes queries.</li><li><strong>BigQuery Data Viewer</strong> (<code>roles/bigquery.dataViewer</code>) on the dataset SPACE needs to read.</li></ul><p>These permissions allow SPACE to execute BigQuery queries, discover dataset metadata, and read tables and views without granting broader write or administrative access.</p><p>If a view references data in another dataset, the Google identity also needs access to the underlying data unless Google BigQuery authorized views or authorized datasets are used.</p><h2 id="creating-or-editing-a-bigquery-connection" tabindex="-1">Creating or editing a BigQuery connection <a class="header-anchor" href="#creating-or-editing-a-bigquery-connection" aria-label="Permalink to &quot;Creating or editing a BigQuery connection&quot;">​</a></h2><p>Choose <strong>New connection</strong>, or open an existing Google BigQuery connection.</p><p>Configure:</p><ul><li><strong>Connection Type</strong> – Google BigQuery.</li><li><strong>Environment Type</strong> – descriptive label such as Production, UAT, QA, Development, or Sandbox.</li><li><strong>Name</strong> – friendly name shown throughout SPACE.</li><li><strong>Project ID</strong> – Google Cloud project that SPACE will use.</li><li><strong>Dataset</strong> – BigQuery dataset associated with the connection.</li></ul><p>Then configure <strong>User credentials</strong> using Google OAuth or a Google service account.</p><h2 id="user-credentials" tabindex="-1">User credentials <a class="header-anchor" href="#user-credentials" aria-label="Permalink to &quot;User credentials&quot;">​</a></h2><p>SPACE supports two authentication options for interactive use:</p><table tabindex="0"><thead><tr><th>Authentication</th><th>Identity used to access BigQuery</th></tr></thead><tbody><tr><td><strong>Google OAuth (SSO)</strong></td><td>Each SPACE user authenticates with their own Google account and uses their existing Google Cloud IAM permissions.</td></tr><tr><td><strong>Google Service Account</strong></td><td>All SPACE users with access to the connection use the same configured Google service account and its BigQuery permissions.</td></tr></tbody></table><h3 id="google-oauth-sso" tabindex="-1">Google OAuth (SSO) <a class="header-anchor" href="#google-oauth-sso" aria-label="Permalink to &quot;Google OAuth (SSO)&quot;">​</a></h3><p>Use Google OAuth when individual users should access BigQuery with their own Google identity and existing Google Cloud permissions.</p><p>In Google Cloud:</p><ol><li>Ensure the <strong>BigQuery API</strong> is enabled.</li><li>Configure the Google OAuth application as appropriate for your organization.</li><li>Create an OAuth client with application type <strong>Web application</strong>.</li><li>Copy the exact <strong>Authorized Redirect URI</strong> displayed by SPACE into the OAuth client&#39;s authorized redirect URIs.</li><li>Copy the resulting <strong>Client ID</strong> and <strong>Client Secret</strong> into the SPACE connection.</li></ol><p>Each SPACE user who uses the connection must have the required BigQuery permissions, either directly or through Google groups.</p><p>The first time a user accesses the connection, SPACE starts the Google OAuth flow. The user signs in with Google and grants access. Future requests can reuse the stored OAuth authorization while Google Cloud IAM continues to control the data available to that user.</p><h3 id="google-service-account" tabindex="-1">Google Service Account <a class="header-anchor" href="#google-service-account" aria-label="Permalink to &quot;Google Service Account&quot;">​</a></h3><p>Use <strong>Google Service Account</strong> when the connection should use one centrally managed Google identity for all authorized SPACE users.</p><p>In Google Cloud:</p><ol><li>Create or select a dedicated service account.</li><li>Grant it <strong>BigQuery Job User</strong> on the required project.</li><li>Grant it <strong>BigQuery Data Viewer</strong> on the required dataset.</li><li>Create a JSON key for the service account.</li><li>Transfer the JSON securely to the SPACE administrator.</li></ol><p>In SPACE, select <strong>Google Service Account</strong> and paste the complete JSON key into <strong>Service Account Credentials</strong>.</p><p>The JSON contains private-key material and should be treated as a sensitive credential.</p><p>No individual Google login is required when this authentication method is used. All SPACE users of the connection operate with the BigQuery permissions assigned to the service account.</p><h2 id="which-user-authentication-should-you-use" tabindex="-1">Which user authentication should you use? <a class="header-anchor" href="#which-user-authentication-should-you-use" aria-label="Permalink to &quot;Which user authentication should you use?&quot;">​</a></h2><p>Use <strong>Google OAuth (SSO)</strong> when you want:</p><ul><li>each user to authenticate with their own Google account;</li><li>existing Google Cloud IAM permissions to remain effective;</li><li>different users to have different BigQuery access;</li><li>per-user identity and auditability.</li></ul><p>Use <strong>Google Service Account</strong> when you want:</p><ul><li>one centrally managed BigQuery identity;</li><li>the same underlying BigQuery permissions for users of the SPACE connection;</li><li>no individual Google login for each SPACE user.</li></ul><p>For organizations that already manage BigQuery security at the individual-user or Google-group level, Google OAuth is generally the more natural model. A service account is simpler when one shared identity is appropriate.</p><h2 id="job-credentials" tabindex="-1">Job credentials <a class="header-anchor" href="#job-credentials" aria-label="Permalink to &quot;Job credentials&quot;">​</a></h2><p>Job authentication is configured separately from interactive user authentication.</p><p>For Google BigQuery, <strong>Job credentials support Google Service Account authentication only</strong>.</p><p>Paste the complete service-account JSON into <strong>Service Account Credentials</strong>. SPACE can then use that service account for supported non-interactive jobs that need access to the BigQuery connection.</p><p>The service account must have the required BigQuery permissions for the configured project and dataset.</p><p>Use <strong>Test connection</strong> to verify the configured credentials and access before relying on the connection in automated workflows.</p>',42)]))}const p=o(r,[["render",a]]);export{h as __pageData,p as default};
